CREATE TABLE `tokencontainer` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(100) NOT NULL,
  `description` varchar(1024) DEFAULT NULL,
  `serial` varchar(40) NOT NULL,
  `last_seen` datetime(6) DEFAULT NULL,
  `last_updated` datetime(6) DEFAULT NULL,
  `template_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_tokencontainer_serial` (`serial`),
  KEY `tokencontainertemplate_id` (`template_id`),
  CONSTRAINT `tokencontainertemplate_id` FOREIGN KEY (`template_id`) REFERENCES `tokencontainertemplate` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

