  `id` int NOT NULL AUTO_INCREMENT,
  `key` varchar(255) NOT NULL,
  `value` text,
  `type` varchar(100) DEFAULT NULL,
  `description` varchar(2000) DEFAULT NULL,
  `container_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `container_id_constraint` (`container_id`,`key`),
  KEY `ix_tokencontainerinfo_container_id` (`container_id`),
  CONSTRAINT `tokencontainerinfo_ibfk_1` FOREIGN KEY (`container_id`) REFERENCES `tokencontainer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

