  `user_id` varchar(320) DEFAULT NULL,
  `realm_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `container_id` (`container_id`),
  KEY `realm_id` (`realm_id`),
  KEY `ix_tokencontainerowner_user_id` (`user_id`),
  KEY `ix_tokencontainerowner_resolver` (`resolver`),
  CONSTRAINT `tokencontainerowner_ibfk_1` FOREIGN KEY (`container_id`) REFERENCES `tokencontainer` (`id`),
  CONSTRAINT `tokencontainerowner_ibfk_2` FOREIGN KEY (`realm_id`) REFERENCES `realm` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

