CREATE TABLE `user_lock_state` (
  `resolver` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `uid` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `realm` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `user_role` varchar(20) NOT NULL,
  `lock_expires_at` datetime(6) DEFAULT NULL,
  `lock_cause` varchar(20) NOT NULL,
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `locked_at` datetime(6) NOT NULL,
  PRIMARY KEY (`resolver`,`uid`,`realm`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `usercache` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(64) DEFAULT NULL,
  `used_login` varchar(64) DEFAULT NULL,
  `resolver` varchar(120) DEFAULT NULL,
  `user_id` varchar(320) DEFAULT NULL,
  `timestamp` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_usercache_user_id` (`user_id`),
  KEY `ix_usercache_used_login` (`used_login`),
  KEY `ix_usercache_timestamp` (`timestamp`),
  KEY `ix_usercache_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `usersetting` (
  `id` int NOT NULL AUTO_INCREMENT,
  `subject_type` varchar(20) NOT NULL,
  `username` varchar(320) DEFAULT NULL,
  `user_id` varchar(320) DEFAULT NULL,
  `resolver` varchar(120) DEFAULT NULL,
  `realm_id` int DEFAULT NULL,
  `subject_hash` varchar(64) NOT NULL,
  `settings` json DEFAULT NULL,
  `last_modified` datetime(6) DEFAULT NULL,
  `node` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usersetting_subject` (`subject_hash`),
  KEY `realm_id` (`realm_id`),
  KEY `ix_usersetting_subject_type_username` (`subject_type`,`username`),
  KEY `ix_usersetting_user` (`user_id`,`resolver`,`realm_id`),
  CONSTRAINT `usersetting_ibfk_1` FOREIGN KEY (`realm_id`) REFERENCES `realm` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

SET FOREIGN_KEY_CHECKS = 1;
